    reg [3:0] index;
    reg [9:0] keypress_array[0:10] = {10'b0000000001, 10'b0000000010, 10'b0000000100, 10'b0000001000, 10'b0000010000, 10'b0000100000, 10'b0001000000, 10'b0010000000, 10'b0100000000, 10'b1000000000, 10'b0000000001};
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            index <= 0;
            keypress <= 0;
        end
        else begin
            if (counter == 20) begin
                keypress <= keypress_array[index];
                counter <= 0;
                index <= index + 1;
                if (index == 10) begin
                    index <= 0;
                end
            end
            else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

