module eb1_5 #(
	parameter WIDTH = 8,
	parameter S0 = 3'o0,
	parameter S1 = 3'o1,
	parameter S2 = 3'o2,
	parameter S3 = 3'o3,
	parameter S4 = 3'o4
) (
	input  clk, reset_n,
	input         [WIDTH-1:0] t0_data,
	input                     t0_valid,
	output logic              t0_ready,
	output logic  [WIDTH-1:0] i0_data,
	output logic              i0_valid,
	input                     i0_ready
);
logic [2:0] state, next_state;
logic [WIDTH-1:0] dat0, dat1;
always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		state <= S0;
	end else begin
		state <= next_state;
	end
end
always_comb begin
	next_state = state;
	case (state)
		S0: begin
			if (t0_valid && i0_ready) begin
				next_state = S1;
			end
		end
		S1: begin
			if (t0_valid && i0_ready) begin
				next_state = S2;
			end
		end
		S2: begin
			if (t0_valid && i0_ready) begin
				next_state = S3;
			end
		end
		S3: begin
			if (t0_valid && i0_ready) begin
				next_state = S4;
			end
		end
		S4: begin
			if (t0_valid && i0_ready) begin
				next_state = S1;
			end
		end
		default: begin
			next_state = S0;
		end
	endcase
end
always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		dat0 <= {WIDTH{1'b0}};
		dat1 <= {WIDTH{1'b0}};
	end else begin
		case (state)
			S0: begin
				dat0 <= {WIDTH{1'b0}};
				dat1 <= {WIDTH{1'b0}};
			end
			S1: begin
				dat0 <= t0_data;
				dat1 <= {WIDTH{1'b0}};
			end
			S2: begin
				dat0 <= {WIDTH{1'b0}};
				dat1 <= t0_data;
			end
			S3: begin
				dat0 <= {WIDTH{1'b0}};
				dat1 <= {WIDTH{1'b0}};
			end
			S4: begin
				dat0 <= {WIDTH{1'b0}};
				dat1 <= {WIDTH{1'b0}};
			end
			default: begin
				dat0 <= {WIDTH{1'b0}};
				dat1 <= {WIDTH{1'b0}};
			end
		endcase
	end
end
assign t0_ready = (state == S0) ? 1'b1 : 1'b0;
assign i0_data = (state == S0) ? dat0 : (state == S1) ? dat0 : (state == S2) ? dat1 : (state == S3) ? dat1 : {WIDTH{1'b0}};
assign i0_valid = (state != S0) ? 1'b1 : 1'b0;
endmodule

module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);
reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [3:0]      wr_ptr, rd_ptr;
    reg [3:0]      word_cnt;

    assign data_o = mem[rd_ptr];

    assign prog_full = word_cnt == PROG_FULL;
    assign full = word_cnt == DEPTH;
    assign empty = word_cnt == 0;

    always @(posedge clk or posedge reset_p) begin
        if (reset_p) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
            word_cnt <= 0;
            overflow <= 0;
            underflow <= 0;
        end else begin
            if (data_we && !full) begin
                mem[wr_ptr] <= data_i;
                wr_ptr <= wr_ptr + 1;
                word_cnt <= word_cnt + 1;
            end
            if (data_rd && !empty) begin
                rd_ptr <= rd_ptr + 1;
                word_cnt <= word_cnt - 1;
            end
            if (data_we && full) begin
                overflow <= 1;
            end
            if (data_rd && empty) begin
                underflow <= 1;
            end
        end
    end

endmodule

