output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
); 

parameter [31:0] H_TOTAL=640;
parameter [31:0] H_SYNC=48;
parameter [31:0] H_BACK=16;
parameter [31:0] H_ACTIVE=640;
parameter [31:0] V_TOTAL=480;
parameter [31:0] V_SYNC=2;
parameter [31:0] V_BACK=3;
parameter [31:0] V_ACTIVE=480;
