module im2_control(
input wire i_CLK_CPU,
input wire i_reset,
input wire i_m1_n,
input wire i_mreq_n,
input wire i_iorq_n,
input wire i_rfsh_n,
input wire [7:0] i_cpu_d,
output wire o_reti_decode,
output wire o_reti_seen
); 

parameter [1:0]
  S_0 = 0,
  S_ED_T4 = 1,
  S_4D_T4 = 2,
  S_CB_T4 = 3;
reg [1:0] state;
reg [7:0] ifetch_d;
reg [7:0] cpu_opcode;
reg ifetch;
reg ifetch_cancel;
wire [7:0] cpu_opcode_decoded;
  assign cpu_opcode_decoded = {cpu_opcode[7:6],cpu_opcode[4:0]};
  assign o_reti_decode = (state == S_ED_T4) ? 1'b1 : 1'b0;
  assign o_reti_seen = (state == S_CB_T4) ? 1'b1 : 1'b0;
  always @(posedge i_CLK_CPU, posedge i_reset) begin
    if((i_reset == 1'b1)) begin
      state <= S_0;
    end else begin
      case(state)
      S_0 : begin
        if((ifetch == 1'b1)) begin
          state <= S_ED_T4;
        end
      end
      S_ED_T4 : begin
        if((ifetch_cancel == 1'b1)) begin
          state <= S_0;
        end
        else if((cpu_opcode_decoded == 8'b11000000)) begin
          state <= S_4D_T4;
        end
        else if((cpu_opcode_decoded == 8'b11000001)) begin
          state <= S_CB_T4;
        end
      end
      S_4D_T4 : begin
        if((ifetch_cancel == 1'b1)) begin
          state <= S_0;
        end
      end
      S_CB_T4 : begin
        if((ifetch_cancel == 1'b1)) begin
          state <= S_0;
        end
      end
      default : begin
        state <= S_0;
      end
      endcase
    end
  end
  always @(i_cpu_d, i_m1_n, i_mreq_n, i_iorq_n, i_rfsh_n, i_CLK_CPU, i_reset) begin
    if((i_reset == 1'b1)) begin
      ifetch_d <= 8'b00000000;
      cpu_opcode <= 8'b00000000;
      ifetch <= 1'b0;
      ifetch_cancel <= 1'b0;
    end else begin
      ifetch_d <= i_cpu_d;
      ifetch <= i_m1_n & i_mreq_n & i_iorq_n & i_rfsh_n;
      ifetch_cancel <= (i_m1_n == 1'b0) & (i_mreq_n == 1'b0) & (i_iorq_n == 1'b0) & (i_rfsh_n == 1'b0);
      cpu_opcode <= ifetch_d;
    end
  end
endmodule

module MUX_Rd(
