    input [31 : 0] dmem,
    input [31 : 0] add8,
    input [31 : 0] cp0,
    input [31 : 0] lo,
    input [31 : 0] hi,
    input [31 : 0] mul_r1,
    input [31 : 0] clz,
    input [2 : 0] M,
    output reg [31:0] res
);
always @(*) begin
        case(M)
            3'b000: res = alu;
            3'b001: res = dmem;
            3'b010: res = add8;
            3'b011: res = cp0;
            3'b100: res = lo;
            3'b101: res = hi;
            3'b110: res = mul_r1;
            3'b111: res = clz;
            default: res = 32'hxxxx;
        endcase
    end
endmodule

