module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
); 

parameter [1:0]
  reset = 0,
  idle = 1,
  running = 2,
  complete = 3;
reg [1:0] current_state = reset;
reg [1:0] next_state = reset;
  always @(posedge clk) begin
    if((resetn == 1'b0)) begin
      current_state <= reset;
    end
    else begin
      current_state <= next_state;
    end
  end
  always @(current_state, go, WREADY) begin
    case(current_state)
    reset : begin
      next_state <= reset;
      done <= 1'b0;
      WDATA <= {32{1'b0}};
      WSTRB <= {4{1'b0}};
      WVALID <= 1'b0;
    end
    idle : begin
      if((go == 1'b1)) begin
        next_state <= running;
        done <= 1'b0;
        WDATA <= data;
        WSTRB <= 4'b1111;
        WVALID <= 1'b1;
      end
      else begin
        next_state <= idle;
        done <= 1'b0;
        WDATA <= {32{1'b0}};
        WSTRB <= {4{1'b0}};
        WVALID <= 1'b0;
      end
    end
    running : begin
      if((WREADY == 1'b1)) begin
        next_state <= complete;
        done <= 1'b0;
        WDATA <= {32{1'b0}};
        WSTRB <= {4{1'b0}};
        WVALID <= 1'b0;
      end
      else begin
        next_state <= running;
        done <= 1'b0;
        WDATA <= data;
        WSTRB <= 4'b1111;
        WVALID <= 1'b1;
      end
    end
    complete : begin
      next_state <= complete;
      done <= 1'b1;
      WDATA <= {32{1'b0}};
      WSTRB <= {4{1'b0}};
      WVALID <= 1'b0;
    end
    default : begin
      next_state <= reset;
      done <= 1'b0;
      WDATA <= {32{1'b0}};
      WSTRB <= {4{1'b0}};
      WVALID <= 1'b0;
