module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 0, DATA0 = 1, DATA1 = 2;
   reg [1:0] state, next_state;
   reg [35:0] data0, data1;
   reg src0_rdy, src1_rdy;
   reg eof;
   always @(posedge clk or posedge reset) begin
      if (reset) begin
         state <= IDLE;
         src0_rdy <= 0;
         src1_rdy <= 0;
      end else begin
         state <= next_state;
         src0_rdy <= src0_rdy_o;
         src1_rdy <= src1_rdy_o;
      end
   end
   always @(state, data_i, src_rdy_i, dst0_rdy_i, dst1_rdy_i) begin
      next_state = state;
      src0_rdy_o = 0;
      src1_rdy_o = 0;
      data0_o = 0;
      data1_o = 0;
      dst_rdy_o = 0;
      eof = 0;
      case (state)
         IDLE: begin
            if (src_rdy_i) begin
               next_state = DATA0;
               src0_rdy_o = 1;
               src1_rdy_o = 1;
            end
         end
         DATA0: begin
            if (dst0_rdy_i) begin
               next_state = DATA1;
               src0_rdy_o = 0;
               src1_rdy_o = 1;
            end else if (eof) begin
               next_state = IDLE;
               src0_rdy_o = 0;
               src1_rdy_o = 0;
            end
         end
         DATA1: begin
            if (dst1_rdy_i) begin
               next_state = DATA0;
               src0_rdy_o = 1;
               src1_rdy_o = 0;
            end else if (eof) begin
               next_state = IDLE;
               src0_rdy_o = 0;
               src1_rdy_o = 0;
            end
         end
      endcase
      if (state == DATA0 || state == DATA1) begin
         if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
            data0_o = data_i[35:0];
            data1_o = data_i[35:0];
            dst_rdy_o = 1;
         end else if (data_i[35:0] == match_data) begin
            data0_o = data_i[35:0];
            dst_rdy_o = 1;
         end else if (data_i[35:0] == match_mask) begin
            data1_o = data_i[35:0];
            dst_rdy_o = 1;
         end
         if (data_i[35]) begin
            eof = 1;
         end
      end
   end
endmodule

