    reg [AW-1:0] cached_addr0;
    reg [AW-1:0] cached_addr1;
    reg [DW-1:0] cached_data0;
    reg [DW-1:0] cached_data1;
    reg [AW-1:0] subaddr;
    reg good;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            good <= 1'b0;
        end else begin
            good <= 1'b1;
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            req <= 1'b0;
        end else begin
            if (addr_ok && addr_req != 0) begin
                if (we) begin
                    if (addr_req[AW-1:AW-DW] == addr[AW-1:AW-DW]) begin
                        cached_data0 <= din;
                        cached_data1 <= din;
                    end else begin
                        cached_data0 <= 0;
                        cached_data1 <= 0;
                    end
                    good <= 1'b1;
                end
                if (good) begin
                    if (addr_req[AW-1:AW-DW] == addr[AW-1:AW-DW]) begin
                        req <= 1'b1;
                    end else begin
                        req <= 1'b0;
                    end
                end else begin
                    req <= 1'b0;
                end
            end else begin
                req <= 1'b0;
            end
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            addr_req <= 0;
        end else begin
            if (addr_ok) begin
                if (DW == 8) begin
                    addr_req <= {addr[AW-1:AW-3], 3'b000};
                end else if (DW == 16) begin
                    addr_req <= {addr[AW-1:AW-4], 4'b0000};
                end else if (DW == 32) begin
                    addr_req <= {addr[AW-1:AW-5], 5'b00000};
                end
            end else begin
                addr_req <= 0;
            end
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            cached_addr0 <= 0;
            cached_addr1 <= 0;
        end else begin
            if (addr_ok) begin
                if (addr_req[AW-1:AW-DW] == addr[AW-1:AW-DW]) begin
                    cached_addr0 <= addr;
                    cached_addr1 <= addr;
                end else begin
                    cached_addr0 <= 0;
                    cached_addr1 <= 0;
                end
            end else begin
                cached_addr0 <= 0;
                cached_addr1 <= 0;
            end
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            subaddr <= 0;
        end else begin
            if (addr_ok) begin
                subaddr <= addr[AW-DW-1:0];
            end else begin
                subaddr <= 0;
            end
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            data_ok <= 1'b0;
        end else begin
            if (addr_ok) begin
                if (addr_req[AW-1:AW-DW] == addr[AW-1:AW-DW]) begin
                    data_ok <= 1'b1;
                end else begin
                    data_ok <= 1'b0;
                end
            end else begin
                data_ok <= 1'b0;
            end
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sdram_addr <= 0;
        end else begin
            if (addr_ok) begin
                sdram_addr <= addr_req + offset;
            end else begin
                sdram_addr <= 0;
            end
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            dout <= 0;
        end else begin
            if (addr_ok) begin
                if (addr_req[AW-1:AW-DW] == addr[AW-1:AW-DW]) begin
                    if (subaddr[DW-1:0] == 0) begin
                        dout <= cached_data0;
                    end else begin
                        dout <= cached_data1;
                    end
                end else begin
                    dout <= 0;
                end
