module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
  reg [7:0] data;
  reg       ready;
  always @(posedge clock) begin
    if (reset) begin
      state <= 4'h0;
      data  <= 8'h0;
      ready <= 1'b0;
    end else begin
      case (state)
        4'h0: begin
          if (io_valid) begin
            data <= io_bits;
            state <= 4'h1;
          end else begin
            state <= 4'h0;
          end
        end
        4'h1: begin
          if (tick) begin
            state <= 4'h2;
          end
        end
        4'h2: begin
          if (tick) begin
            state <= 4'h3;
          end
        end
        4'h3: begin
          if (tick) begin
            state <= 4'h0;
            ready <= 1'b1;
          end
        end
        default: begin
          state <= 4'h0;
          ready <= 1'b0;
        end
      endcase
      if (tick) begin
        data <= {data[6:0], 1'b0};
      end
    end
  end
  assign io_ready = ready;
  assign tx = data[7];
endmodule

