    reg [13:0] chr_bank;
    reg prg_allow;
    reg chr_allow;
    reg vram_a10;
    reg vram_ce;
    always @(posedge clk) begin
        if (reset) begin
            prg_bank <= 0;
            chr_bank <= 0;
            prg_allow <= 0;
            chr_allow <= 0;
            vram_a10 <= 0;
            vram_ce <= 0;
