                chr_bank <= chr_din[13:0];
            end
            if (chr_read) begin
                chr_allow <= 1;
            end else begin
                chr_allow <= 0;
            end
            vram_a10 <= 0;
            vram_ce <= 0;
        end
    end
    assign prg_aout = prg_bank[15:0] << 10 | prg_ain[15:0];
