module dhcp_client_m_axis_open_port_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam
    DEPTH = 1 << DEPTH_BITS;

reg [DATA_BITS-1:0] mem[0:DEPTH-1];
reg [DEPTH_BITS-1:0] index;

assign empty_n = (index != 0);
assign full_n  = (index != DEPTH-1);
assign dout    = mem[index];

always @(posedge clk or posedge aclr) begin
    if (aclr) begin
        index <= '0;
    end else begin
        if (write && ~read) begin
            index <= index + 1;
        end else if (read && ~write) begin
            index <= index - 1;
        end
    end
end

always @(posedge clk or posedge aclr) begin
    if (aclr) begin
        mem[0] <= '0;
    end else begin
        if (write) begin
            mem[0] <= din;
        end
    end
end

genvar i;
generate
    for (i = 1; i < DEPTH; i = i + 1) begin : gen_mem
        always @(posedge clk or posedge aclr) begin
            if (aclr) begin
                mem[i] <= '0;
            end else begin
                if (write && ~read) begin
                    mem[i] <= mem[i-1];
                end
            end
        end
    end
endgenerate

endmodule

