module Math_Divide(
	input CLK, 
	input [31:0] Divisor, 
	input [31:0] Divider,
	output [31:0] result, 
	output [31:0] remainder,
	inout done 
    );
reg [31:0] divisor, divider, remainder, result;
	reg [31:0] counter;
	reg done_flag;
	always @(posedge CLK) begin
		if (done_flag == 1'b0) begin
			divisor <= Divisor;
			divider <= Divider;
			remainder <= Divisor;
			result <= 0;
			counter <= 0;
			done_flag <= 1'b1;
		end
		else begin
			if (remainder >= divider) begin
				remainder <= remainder - divider;
				result <= result + 1;
				counter <= counter + 1;
			end
			else begin
				done_flag <= 1'b0;
			end
		end
	end
	assign done = done_flag;
	assign remainder = remainder;
	assign result = result;
endmodule

