	input [WIDTH-1:0] in;
	input up, down, set, clk;
	output reg [WIDTH-1:0] out;
parameter WIDTH = 8;
	parameter MAX = 2**WIDTH - 1;
	wire [2:0] uds = {up, down, set};
	always @(posedge clk) begin
		if (uds == 3'b001) begin
			out <= in;
		end else if (uds == 3'b010) begin
			if (out == MAX) begin
				out <= 0;
			end else begin
				out <= out + 1;
			end
		end else if (uds == 3'b100) begin
			if (out == 0) begin
				out <= MAX;
			end else begin
				out <= out - 1;
			end
		end else begin
			out <= out;
		end
	end
	initial begin
		out <= 0;
	end
endmodule

