always @(posedge clk or negedge arst)
begin
	if (!arst)
		r_b_1P <= 0;
	else
		r_b_1P <= b;
end

always @(posedge clk or negedge arst)
begin
	if (!arst)
		r_q_P[0] <= 0;
	else
