module QueueCompatibility_14( 
  input        clock, 
  input        reset, 
  output       io_enq_ready, 
  input        io_enq_valid, 
  input  [3:0] io_enq_bits_tl_state_size, 
  input  [1:0] io_enq_bits_tl_state_source, 
  input        io_deq_ready, 
  output       io_deq_valid, 
  output [3:0] io_deq_bits_tl_state_size, 
  output [1:0] io_deq_bits_tl_state_source 
);
wire do_enq = io_enq_ready && io_enq_valid; 
  wire do_deq = io_deq_ready && io_deq_valid; 
  wire [3:0] state_size = io_enq_bits_tl_state_size; 
  wire [1:0] state_source = io_enq_bits_tl_state_source; 
  reg [3:0] maybe_full; 
  always @(posedge clock) begin
    if (reset) begin
      maybe_full <= 0;
    end else begin
      if (do_enq) begin
        maybe_full <= maybe_full + 1;
      end
      if (do_deq) begin
        maybe_full <= maybe_full - 1;
      end
    end
  end
  assign io_enq_ready = (maybe_full == 0);
  assign io_deq_valid = (maybe_full != 0);
  assign io_deq_bits_tl_state_size = state_size;
  assign io_deq_bits_tl_state_source = state_source;
endmodule

module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
);
reg [3*NBITS-1:0] rdata0 [0 :NUM_RDATA/4-1];
  reg [3*NBITS-1:0] rdata1 [0 :NUM_RDATA/4-1];
  reg [3*NBITS-1:0] rdata2 [0 :NUM_RDATA/4-1];
  reg [3*NBITS-1:0] rdata3 [0 :NUM_RDATA/4-1];
  reg [3*NBITS-1:0] rdata0_out;
  reg [3*NBITS-1:0] rdata1_out;
  reg [3*NBITS-1:0] rdata2_out;
  reg [3*NBITS-1:0] rdata3_out;
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      rdata0_out <= {3*NBITS{1'b0}};
      rdata1_out <= {3*NBITS{1'b0}};
      rdata2_out <= {3*NBITS{1'b0}};
      rdata3_out <= {3*NBITS{1'b0}};
    end else begin
      if (valid_rd) begin
        rdata0_out <= rdata0[0];
        rdata1_out <= rdata1[0];
        rdata2_out <= rdata2[0];
        rdata3_out <= rdata3[0];
        for (integer i = 1; i < NUM_RDATA/4; i = i + 1) begin
          rdata0_out <= rdata0_out | rdata0[i];
          rdata1_out <= rdata1_out | rdata1[i];
          rdata2_out <= rdata2_out | rdata2[i];
          rdata3_out <= rdata3_out | rdata3[i];
        end
      end
    end
  end
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      rdata0 <= {NUM_RDATA{1'b0}};
      rdata1 <= {NUM_RDATA{1'b0}};
      rdata2 <= {NUM_RDATA{1'b0}};
      rdata3 <= {NUM_RDATA{1'b0}};
    end else begin
      if (valid_rd) begin
        rdata0 <= rdata[0 : NUM_RDATA/4-1];
        rdata1 <= rdata[NUM_RDATA/4 : 2*NUM_RDATA/4-1];
        rdata2 <= rdata[2*NUM_RDATA/4 : 3*NUM_RDATA/4-1];
        rdata3 <= rdata[3*NUM_RDATA/4 : NUM_RDATA-1];
      end
    end
  end
  assign hrdata = rdata0_out | rdata1_out | rdata2_out | rdata3_out;
endmodule

