module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);
parameter CLK_FREQ = 100000000;
  parameter UART_BPS = 115200;
  parameter BPS_CNT = CLK_FREQ / UART_BPS;
  parameter TX_FLAG = 1'b1;
  parameter TX_DATA = 8'b00000000;
  parameter TX_CNT = 8'b00000000;
  parameter CLK_CNT = 8'b00000000;
  reg tx_flag;
  reg [7:0] tx_data;
  reg [7:0] clk_cnt;
  reg [7:0] tx_cnt;
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      tx_flag <= TX_FLAG;
      tx_data <= TX_DATA;
      clk_cnt <= CLK_CNT;
      tx_cnt <= TX_CNT;
    end else begin
      if (uart_en) begin
        tx_flag <= TX_FLAG;
        tx_data <= uart_din;
        clk_cnt <= CLK_CNT;
        tx_cnt <= TX_CNT;
      end else begin
        if (tx_flag) begin
          if (tx_cnt == 8) begin
            tx_flag <= TX_FLAG;
            tx_data <= TX_DATA;
            clk_cnt <= CLK_CNT;
            tx_cnt <= TX_CNT;
          end else begin
            tx_flag <= TX_FLAG;
            tx_data <= TX_DATA;
            clk_cnt <= CLK_CNT;
            tx_cnt <= tx_cnt + 1;
          end
        end else begin
          if (clk_cnt == BPS_CNT) begin
            tx_flag <= TX_FLAG;
            tx_data <= TX_DATA;
            clk_cnt <= CLK_CNT;
            tx_cnt <= TX_CNT;
          end else begin
            tx_flag <= TX_FLAG;
            tx_data <= TX_DATA;
            clk_cnt <= clk_cnt + 1;
            tx_cnt <= TX_CNT;
          end
        end
      end
      if (tx_cnt == 9) begin
        tx_flag <= TX_FLAG;
        tx_data <= TX_DATA;
        clk_cnt <= CLK_CNT;
        tx_cnt <= TX_CNT;
      end
    end
  end
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      uart_txd <= 1'b0;
    end else begin
      if (tx_flag) begin
        uart_txd <= tx_data[tx_cnt];
      end else begin
        uart_txd <= 1'b0;
      end
    end
  end
endmodule

