module shift #(
    parameter DATA_WIDTH = 16,
    parameter DATA_TYPE = "unsigned", 
    parameter SHIFT_VALUE = 1,      
    parameter ASYNC = 0,             
    parameter OVERFLOW_WARNING = 1
) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] din,

    output wire [DATA_WIDTH-1:0] dout,
    output wire [1:0] warning
);
reg [DATA_WIDTH-1:0] dout_reg;
    wire [DATA_WIDTH-1:0] dout_wire;

    generate
        if (ASYNC == 0) begin
            always @(posedge clk) begin
                dout_reg <= din << SHIFT_VALUE;
            end
        end else begin
            assign dout_wire = din << SHIFT_VALUE;
        end
    endgenerate

    assign dout = ASYNC ? dout_wire : dout_reg;

    generate
        if (DATA_TYPE == "signed") begin
            if (OVERFLOW_WARNING == 1) begin
                assign warning = (din[DATA_WIDTH-1] == 1'b0 && dout[DATA_WIDTH-1] == 1'b1) ? 2'b10 : (din[DATA_WIDTH-1] == 1'b1 && dout[DATA_WIDTH-1] == 1'b0) ? 2'b01 : 2'b00;
            end else begin
                assign warning = 2'b00;
            end
        end else begin
            if (OVERFLOW_WARNING == 1) begin
                assign warning = (din[DATA_WIDTH-1] == 1'b0 && dout[DATA_WIDTH-1] == 1'b1) ? 2'b10 : 2'b00;
            end else begin
                assign warning = 2'b00;
            end
        end
    endgenerate

endmodule

