module alu_32 (
  input_a,
  input_b,
  control,
  zero, 
  cout,
  err_overflow,
  err_invalid_control,
  result
); 

input wire [WORD_SIZE-1:0]	input_a;
input wire [WORD_SIZE-1:0]	input_b;
input wire [CONTROL_SIGNAL_SIZE-1:0]	control;
output wire       zero;
output reg	      cout;
output reg	      err_overflow;
output reg	      err_invalid_control;
output reg [WORD_SIZE-1:0]	result;
parameter WORD_SIZE = 32;
parameter CONTROL_SIGNAL_SIZE = 4;
parameter AND = 0;
parameter OR = 1;
parameter ADD = 2;
parameter ADD_UNSIGNED = 3;
parameter SUB = 4;
parameter SLT = 5;
parameter NOR = 6;

always @(*) begin
  case (control)
    AND: begin
      result = input_a & input_b;
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
      zero = (result == 0);
    end
    OR: begin
      result = input_a | input_b;
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
      zero = (result == 0);
    end
    ADD: begin
      result = input_a + input_b;
      cout = result[WORD_SIZE-1];
      err_overflow = (result[WORD_SIZE-1] != input_a[WORD_SIZE-1] && result[WORD_SIZE-1] != input_b[WORD_SIZE-1]);
      err_invalid_control = 0;
      zero = (result == 0);
    end
    ADD_UNSIGNED: begin
      result = input_a + input_b;
      cout = result[WORD_SIZE-1];
      err_overflow = 0;
      err_invalid_control = 0;
      zero = (result == 0);
    end
    SUB: begin
      result = input_a - input_b;
      cout = result[WORD_SIZE-1];
      err_overflow = (result[WORD_SIZE-1] != input_a[WORD_SIZE-1] && result[WORD_SIZE-1] != input_b[WORD_SIZE-1]);
      err_invalid_control = 0;
      zero = (result == 0);
    end
    SLT: begin
      result = input_a < input_b;
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
      zero = (result == 0);
    end
    NOR: begin
      result = ~(input_a | input_b);
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
      zero = (result == 0);
    end
    default: begin
      result = 0;
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 1;
      zero = 0;
    end
  endcase
end

endmodule

