module diffeq_f_systemC(aport, dxport, xport, yport, uport, clk, reset);

input clk;
input reset;
input [31:0]aport;
input [31:0]dxport;
output [31:0]xport;
output [31:0]yport;
output [31:0]uport;
reg [31:0]xport;
reg [31:0]yport;
reg [31:0]uport;

always @(posedge clk or posedge reset) begin
	if (reset == 1) begin
		xport <= 0;
		yport <= 0;
		uport <= 0;
	end
	else begin
		xport <= (uport + dxport) * (uport + dxport) + aport;
		yport <= (uport + dxport) * (uport + dxport) + aport;
		uport <= (uport + dxport) * (uport + dxport) + aport;
	end
end

endmodule

module top(full_rst, height, width, allowed_cycles, full_clk);output  [23:0] allowed_cycles;input  full_clk;input  full_rst;output  [15:0] height;output  [15:0] width;
reg [23:0] allowed_cycles_reg;
reg [15:0] height_reg;
reg [15:0] width_reg;
wire [23:0] allowed_cycles_next;
wire [15:0] height_next;
wire [15:0] width_next;
assign allowed_cycles = allowed_cycles_reg;
assign height = height_reg;
assign width = width_reg;
always @(posedge full_clk) begin
    if (full_rst == 1'b1) begin
        allowed_cycles_reg <= 24'h000000;
        height_reg <= 16'h0000;
        width_reg <= 16'h0000;
    end else begin
        allowed_cycles_reg <= allowed_cycles_next;
        height_reg <= height_next;
        width_reg <= width_next;
    end
end
always @(allowed_cycles_reg, height_reg, width_reg) begin
    allowed_cycles_next = allowed_cycles_reg;
    height_next = height_reg;
    width_next = width_reg;
    if (full_rst == 1'b1) begin
        allowed_cycles_next = 24'h000000;
        height_next = 16'h0000;
        width_next = 16'h0000;
    end else begin
        allowed_cycles_next = 24'h65b710;
        height_next = 16'h0c00;
        width_next = 16'h1000;
    end
end
endmodule

