module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg mainclk_tmp;
reg updateclk_tmp;
reg capture_tmp;
reg update_tmp;

wire mainclk;
wire updateclk;
wire capture;
wire update;

initial
begin
    mainclk_tmp = 1'b0;
    updateclk_tmp = 1'b0;
    capture_tmp = 1'b0;
    update_tmp = 1'b0;
end

always @ (captnupdt or shiftnld or clk)
begin
    case ({captnupdt, shiftnld})
        2'b10: begin
            updateclk_tmp = clk;
            capture_tmp = 1'b1;
        end
        2'b11: begin
            updateclk_tmp = clk;
            capture_tmp = 1'b1;
        end
        2'b01: begin
            updateclk_tmp = clk;
            capture_tmp = 1'b0;
        end
        default: begin
            mainclk_tmp = clk;
            update_tmp = 1'b1;
        end
    endcase
end

and (mainclk, mainclk_tmp, 1'b1);
and (updateclk, updateclk_tmp, 1'b1);
and (capture, capture_tmp, 1'b1);
and (update, update_tmp, 1'b1);

endmodule

