module ff_d_nand(
    output reg Q,
    input D, CLK, CLR_BAR   
);
parameter Vcc = 1.8;
    parameter C_L = 100;
    parameter t_hmin = 100;
    parameter t_hmax = 100;
    integer counter = 0;
    always @(posedge CLK) begin
        if (CLR_BAR == 1'b0) begin
            Q <= 1'b0;
        end else begin
            Q <= D;
        end
        if (Q != Q) begin
            counter = counter + 1;
            $display("Power dissipation: %d", counter * C_L * Vcc^2);
        end
    end
endmodule

