module gray_Nbits (clk, reset, enable, gray_out);

input wire clk, reset, enable;
output wire [N-1:0]gray_out;
parameter N = 4;
parameter SIZE = N+1;
parameter Zeros = {SIZE{1'b0}};

reg [SIZE-1:0]state;
wire [SIZE-1:0]toggle;

assign gray_out = state[N-1:0];

always @(posedge clk or posedge reset)
begin
	if (reset)
		state <= Zeros;
	else if (enable)
		state <= {1'b1, ~toggle, state[N-1:1]};
end

always @(state)
begin
	toggle[0] = 1'b1;
	toggle[1] = state[0] ^ state[2];
	toggle[2] = state[1] ^ state[3];
	toggle[3] = state[2] ^ state[3];
	toggle[4] = state[3] ^ state[4];
	toggle[5] = state[4] ^ state[5];
	toggle[6] = state[5] ^ state[6];
	toggle[7] = state[6] ^ state[7];
end

endmodule

