module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
localparam [1:0] IDLE = 2'b00;
  localparam [1:0] READY = 2'b01;
  localparam [1:0] RELEASE = 2'b10;

  reg [1:0] state = IDLE;
  reg [1:0] next_state = IDLE;
  reg [23:0] r_count = 0;
  reg [23:0] r_count_next = 0;
  reg [23:0] r_count_max = 0;
  reg [1:0] r_ppfifo_act = 0;
  reg [1:0] r_ppfifo_act_next = 0;
  reg [1:0] r_ppfifo_rdy = 0;
  reg [1:0] r_ppfifo_rdy_next = 0;
  reg [1:0] r_ppfifo_size = 0;
  reg [1:0] r_ppfifo_size_next = 0;
  reg [1:0] r_ppfifo_stb = 0;
  reg [1:0] r_ppfifo_stb_next = 0;
  reg [DATA_WIDTH - 1:0] r_ppfifo_data = 0;
  reg [DATA_WIDTH - 1:0] r_ppfifo_data_next = 0;

  assign o_ppfifo_clk = clk;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      r_count <= 0;
      r_ppfifo_act <= 0;
      r_ppfifo_rdy <= 0;
      r_ppfifo_size <= 0;
      r_ppfifo_stb <= 0;
      r_ppfifo_data <= 0;
    end else begin
      r_count <= r_count_next;
      r_ppfifo_act <= r_ppfifo_act_next;
      r_ppfifo_rdy <= r_ppfifo_rdy_next;
      r_ppfifo_size <= r_ppfifo_size_next;
      r_ppfifo_stb <= r_ppfifo_stb_next;
      r_ppfifo_data <= r_ppfifo_data_next;
    end
  end

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  always @(state, r_ppfifo_rdy, r_ppfifo_size, r_count, i_v_sync, i_h_sync, i_h_blank, i_v_blank, i_data_en, i_rgb) begin
    next_state = state;
    r_count_next = r_count;
    r_ppfifo_act_next = r_ppfifo_act;
    r_ppfifo_rdy_next = r_ppfifo_rdy;
    r_ppfifo_size_next = r_ppfifo_size;
    r_ppfifo_stb_next = r_ppfifo_stb;
    r_ppfifo_data_next = r_ppfifo_data;
    o_ppfifo_act = r_ppfifo_act;
    o_ppfifo_stb = r_ppfifo_stb;
    o_ppfifo_data = r_ppfifo_data;

    case (state)
      IDLE: begin
        if (i_ppfifo_rdy[0] && i_ppfifo_rdy[1]) begin
          next_state = READY;
          r_ppfifo_act_next = 2'b01;
          r_ppfifo_rdy_next = 2'b00;
          r_ppfifo_size_next = i_ppfifo_size;
          r_count_next = 0;
          r_ppfifo_stb_next = 1'b0;
          r_ppfifo_data_next = 0;
        end
      end
      READY: begin
        if (i_v_sync && !i_v_blank) begin
          next_state = RELEASE;
          r_ppfifo_act_next = 2'b00;
          r_ppfifo_rdy_next = 2'b01;
          r_ppfifo_size_next = 0;
          r_count_next = 0;
          r_ppfifo_stb_next = 1'b0;
          r_ppfifo_data_next = 0;
        end else if (i_h_blank) begin
          r_ppfifo_stb_next = 1'b0;
          r_ppfifo_data_next = 0;
        end else if (i_data_en) begin
          r_ppfifo_stb_next = 1'b1;
          r_ppfifo_data_next = i_rgb;
          r_count_next = r_count + 1;
          if (r_count == r_ppfifo_size) begin
            next_state = RELEASE;
            r_ppfifo_act_next = 2'b00;
            r_ppfifo_rdy_next = 2'b01;
            r_ppfifo_size_next = 0;
            r_count_next = 0;
            r_ppfifo_stb_next = 1'b0;
            r_ppfifo_data_next = 0;
          end
        end
      end
      RELEASE: begin
        if (i_ppfifo_rdy[0] && i_ppfifo_rdy[1]) begin
          next_state = READY;
          r_ppfifo_act_next = 2'b01;
          r_ppfifo_rdy_next = 2'b00;
          r_ppfifo_size_next = i_ppfifo_size;
          r_count_next = 0;
          r_ppfifo_stb_next = 1'b0;
          r_ppfifo_data_next = 0;
        end
      end
      default: begin
        next_state = IDLE;
      end
    endcase
  end

endmodule

