module matrix5arb (
   		   input clk,
   		   input rst_n,
   		   input [4:0] req,
   		   output [4:0] grant
   		   );
reg [4:0] state;
   always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
	 state <= 5'b00000;
      end else begin
	 if (req[0] && !req[1] && !req[2] && !req[3] && !req[4]) begin
	    state <= 5'b00001;
	 end else if (req[1] && !req[2] && !req[3] && !req[4]) begin
	    state <= 5'b00010;
	 end else if (req[2] && !req[3] && !req[4]) begin
	    state <= 5'b00011;
	 end else if (req[3] && !req[4]) begin
	    state <= 5'b00100;
	 end else if (req[4]) begin
	    state <= 5'b00101;
	 end else begin
	    state <= 5'b00000;
	 end
      end
   end
   assign grant = state;
endmodule

module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
parameter INSERT_REGISTER = 1;
 parameter DATA_WIDTH = 32;

 reg [DATA_WIDTH-1:0] datain;
 reg datain_valid;
 reg datain_stall;
 reg dataout_stall;
 reg dataout_valid;

 always @(posedge clock or negedge resetn) begin
  if (!resetn) begin
   datain <= 0;
   datain_valid <= 0;
   datain_stall <= 0;
   dataout_stall <= 0;
   dataout_valid <= 0;
  end else begin
   datain <= i_datain;
   datain_valid <= i_datain_valid;
   datain_stall <= o_datain_stall;
   dataout_stall <= i_dataout_stall;
   dataout_valid <= o_dataout_valid;
  end
 end

 always @(*) begin
  if (INSERT_REGISTER == 1) begin
   o_datain_stall = datain_stall;
   o_dataout = datain;
   o_dataout_valid = datain_valid;
  end else begin
   o_datain_stall = 0;
   o_dataout = i_datain;
   o_dataout_valid = i_datain_valid;
  end
 end

endmodule

