module data_deal(
	clk,
	rst_n,
	data_in,
	data_in_sign,

	data_out,
	data_out_sign,
	data_valid,
	data_ok
    );



	input 	clk;
	input 	rst_n;
	input 	[6:0]	data_in;
	input 	data_in_sign;

	output	[6:0]	data_out;
	output	data_out_sign;
	input 	data_valid;
	output	data_ok;
reg 	[6:0]	data_reg;
	reg 	[3:0]	data_regnum;

	assign data_out = data_valid ? data_reg : 7'b0000000;
	assign data_out_sign = data_valid;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			data_reg <= 7'b0000000;
			data_regnum <= 4'b0000;
		end
		else begin
			if (data_valid) begin
				if (data_in_sign) begin
					data_reg <= data_reg + data_in;
				end
				else begin
					data_reg <= data_reg - data_in;
				end
				data_regnum <= data_regnum + 1;
			end
		end
	end

	assign data_ok = (data_regnum == 8) ? (data_reg == 28 || data_reg == 36) : 1'b0;

endmodule

module clk_div(
input wire clk_100MHz,
input wire reset,
output wire clk_100Hz
); 

reg [31:0] ticks = 499999;
reg clk_out = 1'b0;
  always @(posedge clk_100MHz, posedge reset) begin
    if(reset == 1'b1) begin
      ticks <= 499999;
      clk_out <= 1'b0;
    end else begin
      if(ticks == 0) begin
        clk_out <=  ~clk_out;
        ticks <= 499999;
      end
      else begin
        ticks <= ticks - 1;
      end
    end
  end
  assign clk_100Hz = clk_out;
endmodule

