module toe_m_axis_rx_data_rsp_metadata_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
wire         load_p1;
wire         load_p2;
wire         load_p1_from_p2;
wire         s_ready_t;
reg  [1:0]   state;
reg  [1:0]   next;

assign s_ready = s_ready_t;
assign m_data  = data_p1;
assign m_valid = state[0];

assign load_p1 = (state == ZERO && s_valid) ||
                 (state == ONE && s_valid && s_ready) ||
                 (state == TWO && s_ready);
assign load_p2 = s_valid & s_ready;
assign load_p1_from_p2 = (state == TWO);

always @(posedge clk) begin
    if (load_p1) begin
        if (load_p1_from_p2)
            data_p1 <= data_p2;
        else
            data_p1 <= s_data;
    end
end

always @(posedge clk) begin
    if (load_p2) data_p2 <= s_data;
end

always @(posedge clk) begin
    if (~reset)
        state <= ZERO;
    else
        state <= next;
end

always @(*) begin
    case (state)
        ZERO:
            if (s_valid & s_ready)
                next = ONE;
            else
                next = ZERO;
        ONE:
            if (~s_valid & s_ready)
                next = ZERO;
            else if (s_valid & ~s_ready)
                next = TWO;
            else
                next = ONE;
        TWO:
            if (m_ready)
                next = ONE;
            else
                next = TWO;
        default:
            next = ZERO;
    endcase
end

assign s_ready_t = (state == ZERO) ? 1'b1 :
                    (state == ONE) ? 1'b0 :
                    (state == TWO) ? load_p1_from_p2 : 1'b0;

endmodule

module Incer #(
    parameter DATA_WIDTH = 8
)
(clk,arstn,din,dout,mode);

input clk;
input arstn;
input mode;
input [DATA_WIDTH-1:0]din;
output [DATA_WIDTH-1:0]dout;
reg [DATA_WIDTH-1:0]counter;
reg state;

assign dout = counter;

parameter ADD_STATE = 1'b0;
parameter INC_STATE = 1'b1;

always @(posedge clk or negedge arstn) begin
    if(!arstn) begin
        counter <= 0;
        state <= ADD_STATE;
    end
    else begin
        case(state)
            ADD_STATE: begin
                if(mode) begin
                    counter <= din + 1;
                    state <= INC_STATE;
                end
                else begin
                    counter <= din + 2;
                    state <= INC_STATE;
                end
            end
            INC_STATE: begin
                if(mode) begin
                    counter <= counter + 1;
                end
                else begin
                    counter <= 0;
                    state <= ADD_STATE;
                end
            end
        endcase
    end
end

endmodule

