module Control(
		input clk,
		input start,
		output[3:0] direction,
		output ready
	);
reg[2:0] state;
	always @(posedge clk) begin
		if (start) begin
			state <= 3'b000;
		end else begin
			if (state[1:0] == 2'b00) begin
				state <= state;
			end else begin
				state <= state + 1;
			end
		end
	end
	assign direction = state[2:0] == 3'b000 ? 4'b0000 : state[2:0] == 3'b001 ? 4'b0001 : state[2:0] == 3'b010 ? 4'b0010 : state[2:0] == 3'b011 ? 4'b0011 : state[2:0] == 3'b100 ? 4'b0100 : state[2:0] == 3'b101 ? 4'b0101 : state[2:0] == 3'b110 ? 4'b0110 : state[2:0] == 3'b111 ? 4'b0111 : 4'b1000;
	assign ready = state[2:0] == 3'b000 ? 1'b1 : state[2:0] == 3'b001 ? 1'b1 : state[2:0] == 3'b010 ? 1'b1 : state[2:0] == 3'b011 ? 1'b1 : state[2:0] == 3'b100 ? 1'b1 : state[2:0] == 3'b101 ? 1'b1 : state[2:0] == 3'b110 ? 1'b1 : state[2:0] == 3'b111 ? 1'b1 : 1'b0;
endmodule

