module SR_SYNC_LATCH(
input wire CLK,
input wire SET,
input wire RESET,
input wire [DATA_WIDTH - 1:0] DATA_IN,
output wire [DATA_WIDTH - 1:0] LATCH_OUT
); 

parameter [31:0] DATA_WIDTH=32;
reg [DATA_WIDTH - 1:0] latch_out_int;
  always @(posedge CLK) begin
    if((SET == 1'b1 && RESET == 1'b0)) begin
      latch_out_int <= DATA_IN;
    end
    else if((SET == 1'b0 && RESET == 1'b1)) begin
      latch_out_int <= {((DATA_WIDTH - 1)-(0)+1){1'b0}};
    end
  end
  assign LATCH_OUT = latch_out_int;
endmodule

