module binary_to_BCD_ten_bit_tb;
reg [9:0] in;
    wire [3:0] ones, tens, hundreds, thousands;

    binary_to_BCD_ten_bit uut (
        .in(in),
        .ones(ones),
        .tens(tens),
        .hundreds(hundreds),
        .thousands(thousands)
    );

    initial begin
        in = 0;
        $display("in\t\tones\ntens\thundreds\tthousands");
        $display("----\t\t----\t----\t----\t----");
        repeat (1024) begin
            $display("%d\t\t%d\t%d\t%d\t%d", in, ones, tens, hundreds, thousands);
            in = in + 1;
            #1;
        end
    end
endmodule

module FullAdder(
  input wire a, 
  input wire b,
  input wire carry_in,
  output wire sum,
  output wire carry_out
);
assign sum = a ^ b;
  assign carry_out = (a & b) | (carry_in & (a ^ b));
endmodule

