module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg          load_p1;
reg          load_p2;
reg          load_p1_from_p2;
wire         s_ready_t;
reg  [1:0]   state;
reg  [1:0]   next;

assign s_ready = s_ready_t;
assign m_data  = data_p1;
assign m_valid = load_p1;

always @(posedge clk) begin
    if (load_p1_from_p2) begin
        data_p1 <= data_p2;
    end
end


always @(posedge clk) begin
    if (load_p1) begin
        data_p1 <= s_data;
    end
end


always @(posedge clk) begin
    if (load_p2) begin
        data_p2 <= s_data;
    end
end


always @(posedge clk) begin
    if (~reset) begin
        state <= ZERO;
    end else begin
        state <= next;
    end
end


always @(posedge clk) begin
    if (~reset) begin
        s_ready_t <= 1'b0;
    end else begin
        s_ready_t <= s_ready_t_next;
    end
end

wire s_ready_t_next;

always @(*) begin
    case (state)
        ZERO: if (s_valid) begin
            s_ready_t_next = 1'b1;
        end else begin
            s_ready_t_next = 1'b0;
        end
        ONE: if (s_valid & m_ready) begin
            s_ready_t_next = 1'b0;
        end else begin
            s_ready_t_next = 1'b1;
        end
        TWO: if (s_valid & m_ready) begin
            s_ready_t_next = 1'b1;
        end else begin
            s_ready_t_next = 1'b0;
        end
        default: s_ready_t_next = 1'b0;
    endcase
end


always @(posedge clk) begin
    if (~reset) begin
        load_p1 <= 1'b0;
    end else begin
        load_p1 <= load_p1_next;
    end
end

wire load_p1_next;

always @(*) begin
    case (state)
        ZERO: if (s_valid) begin
            load_p1_next = 1'b1;
        end else begin
            load_p1_next = 1'b0;
        end
        ONE: if (s_valid & m_ready) begin
            load_p1_next = 1'b0;
        end else begin
            load_p1_next = 1'b1;
        end
        TWO: if (s_valid & m_ready) begin
            load_p1_next = 1'b1;
        end else begin
            load_p1_next = 1'b0;
        end
        default: load_p1_next = 1'b0;
    endcase
end


always @(posedge clk) begin
    if (~reset) begin
        load_p2 <= 1'b0;
    end else begin
        load_p2 <= load_p2_next;
    end
end

wire load_p2_next;

always @(*) begin
    case (state)
        ZERO: if (s_valid) begin
            load_p2_next = 1'b1;
        end else begin
            load_p2_next = 1'b0;
        end
        ONE: if (s_valid & m_ready) begin
            load_p2_next = 1'b1;
        end else begin
            load_p2_next = 1'b0;
        end
        TWO: if (s_valid & m_ready) begin
            load_p2_next = 1'b0;
        end else begin
            load_p2_next = 1'b1;
        end
        default: load_p2_next = 1'b0;
    endcase
end


always @(posedge clk) begin
    if (~reset) begin
        load_p1_from_p2 <= 1'b0;
    end else begin
        load_p1_from_p2 <= load_p1_from_p2_next;
    end
end

wire load_p1_from_p2_next;

always @(*) begin
    case (state)
        ZERO: if (s_valid) begin
            load_p1_from_p2_next = 1'b0;
        end else begin
            load_p1_from_p2_next = 1'b0;
        end
        ONE: if (s_valid & m_ready) begin
            load_p1_from_p2_next = 1'b0;
        end else begin
            load_p1_from_p2_next = 1'b1;
        end
        TWO: if (s_valid & m_ready) begin
            load_p1_from_p2_next = 1'b1;
        end else begin
            load_p1_from_p2_next = 1'b0;
        end
        default: load_p1_from_p2_next = 1'b0;
    endcase
end


always @(posedge clk) begin
    if (~reset) begin
        next <= ZERO;
    end else begin
        next <= state_next;
    end
end

wire state_next;

always @(*) begin
    case (state)
        ZERO: if (s_valid) begin
            next = ONE;
        end else begin
            next = ZERO;
        end
        ONE: if (s_valid & m_ready) begin
            next = TWO;
        end else begin
            next = ONE;
        end
        TWO: if (s_valid & m_ready) begin
            next = TWO;
        end else begin
            next = ZERO;
        end
        default: next = ZERO;
    endcase
end

endmodule

