module SynFifo #
(
    parameter DATA_WIDTH = 8,
    parameter FIFO_DEPTH = 256
)
(clk,arstn,data_in,wrreq,rdreq,data_out,usedw,empty,full);

input clk;
input arstn;
input [DATA_WIDTH-1:0]data_in;
input wrreq;
input rdreq;
output [DATA_WIDTH-1:0]data_out;
output reg [clog2_FIFO_DEPTH:0]usedw;
output empty;
output full;
parameter clog2_FIFO_DEPTH = $clog2(FIFO_DEPTH);

reg [clog2_FIFO_DEPTH:0]wrptr;
reg [clog2_FIFO_DEPTH:0]rdptr;
reg [DATA_WIDTH-1:0]mem[FIFO_DEPTH-1:0];

assign empty = (usedw == 0);
assign full = (usedw == FIFO_DEPTH-1);
assign data_out = mem[rdptr];

always @(posedge clk or negedge arstn)
begin
    if (!arstn)
        wrptr <= 0;
    else if (wrreq && !full)
        wrptr <= wrptr + 1;
end

always @(posedge clk or negedge arstn)
begin
    if (!arstn)
        rdptr <= 0;
    else if (rdreq && !empty)
        rdptr <= rdptr + 1;
end

always @(posedge clk or negedge arstn)
begin
    if (!arstn)
        usedw <= 0;
    else if (wrreq && !full)
        usedw <= usedw + 1;
    else if (rdreq && !empty)
        usedw <= usedw - 1;
end

always @(posedge clk or negedge arstn)
begin
    if (!arstn)
        mem[0] <= 0;
    else if (wrreq && !full)
        mem[wrptr] <= data_in;
end

endmodule

