module lfsr24(
input wire Clk,
input wire one,
input wire tick,
input wire [6:0] coreCount,
output reg data
); 

reg [23:0] lfsr_p;
reg [23:0] lfsr_n;
  always @(posedge Clk) begin
    if((one == 1'b1)) begin
      lfsr_p <= 24'h020000;
    end
    else if((tick == 1'b1)) begin
      lfsr_n <= lfsr_p;
      if((coreCount < 24)) begin
        lfsr_n[23:0] <= lfsr_p[22:0] ^ lfsr_p[23];
      end
      else begin
        lfsr_n[23:0] <= lfsr_p[22:0] ^ lfsr_p[23];
        lfsr_n[23:0] <= {lfsr_p[23:1],lfsr_p[0]};
      end
      lfsr_p <= lfsr_n;
    end
  end
  always @(lfsr_p) begin
    case(coreCount)
    7'b0000000 : begin
      data <= lfsr_p[0];
    end
    7'b0000001 : begin
      data <= lfsr_p[1];
    end
    7'b0000010 : begin
      data <= lfsr_p[2];
    end
    7'b0000011 : begin
      data <= lfsr_p[3];
    end
    7'b0000100 : begin
      data <= lfsr_p[4];
    end
    7'b0000101 : begin
      data <= lfsr_p[5];
    end
    7'b0000110 : begin
      data <= lfsr_p[6];
    end
    7'b0000111 : begin
      data <= lfsr_p[7];
