module pn_gen_9 (
    input clk,
    input rst,
    input next,
    input [31:0] seed,
    output reg [31:0] num
  );
localparam SEED = 32'h00000000;
  reg [31:0] M_x, M_y, M_z, M_w;
  reg [31:0] M_x_q, M_y_q, M_z_q, M_w_q, M_w_d;
  wire [31:0] t;
  assign t = M_x_q ^ M_y_q;
  always @(posedge clk) begin
    if (rst) begin
      M_x <= SEED;
      M_y <= SEED;
      M_z <= SEED;
      M_w <= {32'h00000000, seed};
    end else begin
      M_x <= M_x_q;
      M_y <= M_y_q;
      M_z <= M_z_q;
      M_w <= M_w_q;
    end
  end
  always @(posedge clk) begin
    M_x_q <= M_x;
    M_y_q <= M_y;
    M_z_q <= M_z;
    M_w_q <= M_w;
    M_w_d <= {32'h00000000, seed};
  end
  always @(posedge clk) begin
    if (next) begin
      M_w <= M_w_d;
      M_x <= M_y;
      M_y <= M_z;
      M_z <= M_w;
    end
  end
  always @(posedge clk) begin
    num <= M_w_q;
  end
endmodule

