      rdaddress_reg <= rdaddress;
   end
   always @(posedge wrclock) begin
      wren_reg <= wren;
   end
   always @(posedge wrclock) begin
      data_reg <= data;
   end
endmodule

module full_adder(
	A,
	B,
	Cin,
	S,
	C
);


input wire	A;
input wire	B;
input wire	Cin;
output wire	S;
output wire	C;
wire	Sum;
wire	Carry;

half_adder ha1(
	.A(A),
	.B(B),
	.Sum(Sum),
	.Carry(Carry)
);

wire	sec_Carry = Cin ^ Sum;

or(C, sec_Carry, Carry);

xor(S, Sum, Cin);

endmodule

