module SumCentroidValues(
input wire [Palavra - 1:0] valueDado,
input wire [PalavraXY - 1:0] valueX,
input wire [PalavraXY - 1:0] valueY,
output wire [PalavraXY - 1:0] o_valueX,
output wire [PalavraXY - 1:0] o_valueY
); 

parameter [31:0] Palavra=64;
parameter [31:0] PalavraXY=32;
reg [PalavraXY - 1:0] s_valueX;
reg [PalavraXY - 1:0] s_valueY;
  always @(valueDado, valueX, valueY) begin
    if((valueDado[Palavra - 1] == 1'b1 && valueX[PalavraXY - 1] == 1'b1)) begin
      s_valueX <= {((PalavraXY - 1)-(0)+1){1'b1}};
    end
    else if((valueDado[Palavra - 1] == 1'b1 && valueY[PalavraXY - 1] == 1'b1)) begin
      s_valueX <= {((PalavraXY - 1)-(0)+1){1'b1}};
    end
    else begin
      s_valueX <= valueX + valueDado;
    end
    if((valueDado[Palavra - 1] == 1'b1 && valueX[PalavraXY - 1] == 1'b1)) begin
      s_valueY <= {((PalavraXY - 1)-(0)+1){1'b1}};
    end
    else if((valueDado[Palavra - 1] == 1'b1 && valueY[PalavraXY - 1] == 1'b1)) begin
      s_valueY <= {((PalavraXY - 1)-(0)+1){1'b1}};
    end
    else begin
      s_valueY <= valueY + valueDado;
    end
  end
  assign o_valueX = s_valueX;
  assign o_valueY = s_valueY;
endmodule

