input clk, reset;

output red,yellow,green;
reg [1:0] state;
reg [1:0] next_state;


assign red = (state == 2'b00);
assign yellow = (state == 2'b01) | (state == 2'b10);
assign green = (state == 2'b11);


always @(posedge clk or posedge reset)
begin
	if (reset)
		state <= 2'b00;
	else
		state <= next_state;
end


always @(*)
begin
	case (state)
		2'b00: next_state = 2'b01;
		2'b01: next_state = 2'b11;
		2'b11: next_state = 2'b10;
		2'b10: next_state = 2'b00;
	endcase
end
endmodule

