module KEY_MUX
(
	input PS2_CLK,
	input PS2_DAT,
	output [9:0]LEDR,
	output [6:0]HEX0,
	output [6:0]HEX1
);
wire [7:0] scan_code;
	wire [7:0] in1, in2, in3;
	wire [7:0] out;

	keyboard key1 (PS2_CLK, PS2_DAT, scan_code);

	display_driver display1 (scan_code, HEX0);
	display_driver display2 (out, HEX1);

	reg [3:0] S, NS;

	always @(scan_code)
	begin
		case (S)
			4'b0000: begin
				in1 = scan_code;
				NS = 4'b0001;
			end
			4'b0001: begin
				in2 = scan_code;
				NS = 4'b0010;
			end
			4'b0010: begin
				in3 = scan_code;
				NS = 4'b0011;
			end
			4'b0011: begin
				out = scan_code;
				NS = 4'b0000;
			end
			default: begin
				NS = 4'b0000;
			end
		endcase
	end

	always @(S)
	begin
		LEDR[3:0] = S;
		LEDR[9:6] = NS;
	end

endmodule

