module voting (a0, a1, a2, a3, a4, out);

input    [2:0]   a0, a1, a2, a3, a4;
output reg [2:0]   out;
wire [2:0]   sum0, sum1, sum2;
wire         error0, error1, error2;

assign sum0 = a0[0] + a1[0] + a2[0] + a3[0] + a4[0];
assign sum1 = a0[1] + a1[1] + a2[1] + a3[1] + a4[1];
assign sum2 = a0[2] + a1[2] + a2[2] + a3[2] + a4[2];

assign error0 = sum0[2] | sum0[1] | sum0[0];
assign error1 = sum1[2] | sum1[1] | sum1[0];
assign error2 = sum2[2] | sum2[1] | sum2[0];

always @(*) begin
    if (error0) begin
        out = 3'b001;
    end else if (error1) begin
        out = 3'b010;
    end else if (error2) begin
        out = 3'b100;
    end else if (sum0[2] > sum1[2] && sum0[2] > sum2[2]) begin
        out = 3'b001;
    end else if (sum1[2] > sum0[2] && sum1[2] > sum2[2]) begin
        out = 3'b010;
    end else if (sum2[2] > sum0[2] && sum2[2] > sum1[2]) begin
        out = 3'b100;
    end else begin
        out = 3'b111;
    end
end

endmodule

