	always @(posedge wrclock) begin
		if (wren_r) begin
			ram_block[wraddr_r] <= wrdata_r;
		end
	end

	always @(posedge rdclock) begin
		read_addr_r <= rdaddress;
	end

	assign q = ram_block[read_addr_r];
endmodule

