module HWORD (
    input CLK,
    input WE,
    input SELW,
    input SELR,
    input [15:0] Di,
    output [15:0] Do
);
wire GCLK = WE & SELW;
    reg [15:0] DFF0, DFF1, DFF2, DFF3;
    always @(posedge CLK) begin
        if (GCLK) begin
            DFF0 <= Di[0];
            DFF1 <= Di[1];
            DFF2 <= Di[2];
            DFF3 <= Di[3];
        end
    end
    always @(posedge CLK) begin
        if (GCLK) begin
            DFF0 <= Di[4];
            DFF1 <= Di[5];
            DFF2 <= Di[6];
            DFF3 <= Di[7];
        end
    end
    always @(posedge CLK) begin
        if (GCLK) begin
            DFF0 <= Di[8];
            DFF1 <= Di[9];
            DFF2 <= Di[10];
            DFF3 <= Di[11];
        end
    end
    always @(posedge CLK) begin
        if (GCLK) begin
            DFF0 <= Di[12];
            DFF1 <= Di[13];
            DFF2 <= Di[14];
            DFF3 <= Di[15];
        end
    end
    assign Do = SELR ? {DFF3, DFF2, DFF1, DFF0} : 16'hzzzz;
endmodule

