module lfsr    (
out             ,  
enable          ,  
clk             ,  
reset              
);


output [7:0] out;

input enable, clk, reset;
reg [7:0] out;

wire linear_feedback = ~ (out[7] ^ out[3]);

always @(posedge clk)
begin
    if (reset)
        out <= 8'b00000000;
    else if (enable)
        out <= {out[6:0], linear_feedback};
end

endmodule

