module bridge_1x2(                                 
    input                           clk,          
    input                           resetn,       
    input                           cpu_data_en,      
    input  [3                   :0] cpu_data_wen,     
    input  [31                  :0] cpu_data_addr,    
    input  [31                  :0] cpu_data_wdata,   
    output [31                  :0] cpu_data_rdata,   
    output                          data_sram_en,     
    output [3                   :0] data_sram_wen,    
    output [31                  :0] data_sram_addr,   
    output [31                  :0] data_sram_wdata,  
    input  [31                  :0] data_sram_rdata,  
    output                          conf_en,          
    output [3                   :0] conf_wen,         
    output [31                  :0] conf_addr,        
    output [31                  :0] conf_wdata,       
    input  [31                  :0] conf_rdata        
);
parameter CONF_ADDR_BASE = 32'h00000000;
parameter CONF_ADDR_MASK = 32'h000000FF;

reg sel_sram;
reg sel_conf;

always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        sel_sram <= 1'b0;
        sel_conf <= 1'b0;
    end else begin
        if (cpu_data_addr[31:24] == 4'h0) begin
            sel_sram <= 1'b1;
            sel_conf <= 1'b0;
        end else begin
            sel_sram <= 1'b0;
            sel_conf <= 1'b1;
        end
    end
end

assign data_sram_en = cpu_data_en & sel_sram;
assign data_sram_wen = cpu_data_wen & sel_sram;
assign data_sram_addr = cpu_data_addr & 32'hFFFFFF00;
assign data_sram_wdata = cpu_data_wdata;

assign conf_en = cpu_data_en & sel_conf;
assign conf_wen = cpu_data_wen & sel_conf;
assign conf_addr = cpu_data_addr & CONF_ADDR_MASK;
assign conf_wdata = cpu_data_wdata;

assign cpu_data_rdata = (sel_sram) ? data_sram_rdata : conf_rdata;

endmodule

module table_011101010(input clk, input rst, input [7:0] addr, output reg match);
always@(posedge clk) begin
    casex (addr)
      8'b01110100: match <= 1'b1;
      default: match <= 1'b0;
    endcase

    if(rst)
      match <= 1'b0;
  end
endmodule

