module MUX2_REQ_BRIDGE
#(
    parameter ID_WIDTH   = 20,
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32,
    parameter AUX_WIDTH  = 6,
    parameter BE_WIDTH   = DATA_WIDTH/8
)
(
    input  logic                              data_req_CH0_i,
    input  logic [ADDR_WIDTH-1:0]             data_add_CH0_i,
    input  logic                              data_wen_CH0_i,
    input  logic [DATA_WIDTH-1:0]             data_wdata_CH0_i,
    input  logic [BE_WIDTH-1:0]               data_be_CH0_i,
    input  logic [ID_WIDTH-1:0]               data_ID_CH0_i,
    input  logic [AUX_WIDTH-1:0]              data_aux_CH0_i,
    output logic                              data_gnt_CH0_o,


    input  logic                              data_req_CH1_i,
    input  logic [ADDR_WIDTH-1:0]             data_add_CH1_i,
    input  logic                              data_wen_CH1_i,
    input  logic [DATA_WIDTH-1:0]             data_wdata_CH1_i,
    input  logic [BE_WIDTH-1:0]               data_be_CH1_i,
    input  logic [ID_WIDTH-1:0]               data_ID_CH1_i,
    input  logic [AUX_WIDTH-1:0]              data_aux_CH1_i,
    output logic                              data_gnt_CH1_o,

    output  logic                             data_req_o,
    output  logic [ADDR_WIDTH-1:0]            data_add_o,
    output  logic                             data_wen_o,
    output  logic [DATA_WIDTH-1:0]            data_wdata_o,
    output  logic [BE_WIDTH-1:0]              data_be_o,
    output  logic [ID_WIDTH-1:0]              data_ID_o,
    output  logic [AUX_WIDTH-1:0]             data_aux_o,
    input   logic                             data_gnt_i,

    input   logic                             clk,
    input   logic                             rst_n
);
logic [1:0]  sel;
    logic [1:0]  rr_flag;
    logic [1:0]  req;
    logic [1:0]  gnt;
    logic [1:0]  data_req;
    logic [1:0]  data_add;
    logic [1:0]  data_wen;
    logic [1:0]  data_wdata;
    logic [1:0]  data_be;
    logic [1:0]  data_ID;
    logic [1:0]  data_aux;

    assign data_req = {data_req_CH0_i, data_req_CH1_i};
    assign data_add = {data_add_CH0_i, data_add_CH1_i};
    assign data_wen = {data_wen_CH0_i, data_wen_CH1_i};
    assign data_wdata = {data_wdata_CH0_i, data_wdata_CH1_i};
    assign data_be = {data_be_CH0_i, data_be_CH1_i};
    assign data_ID = {data_ID_CH0_i, data_ID_CH1_i};
    assign data_aux = {data_aux_CH0_i, data_aux_CH1_i};

    assign data_req_o = data_req[sel];
    assign data_add_o = data_add[sel];
    assign data_wen_o = data_wen[sel];
    assign data_wdata_o = data_wdata[sel];
    assign data_be_o = data_be[sel];
    assign data_ID_o = data_ID[sel];
    assign data_aux_o = data_aux[sel];

    assign data_gnt_CH0_o = gnt[0];
    assign data_gnt_CH1_o = gnt[1];

    always_comb begin
        if (data_req[0] && data_req[1]) begin
            if (rr_flag[0]) begin
                sel = 0;
            end else begin
                sel = 1;
            end
        end else if (data_req[0]) begin
            sel = 0;
        end else if (data_req[1]) begin
            sel = 1;
        end else begin
            sel = 0;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rr_flag <= 2'b00;
        end else begin
            rr_flag <= {rr_flag[0], data_gnt_i};
        end
    end

    always_comb begin
        req = {data_req_CH0_i, data_req_CH1_i};
        gnt = {data_gnt_CH0_i, data_gnt_CH1_i};
        if (req[0] && req[1]) begin
            if (rr_flag[0]) begin
                gnt[0] = 1'b0;
                gnt[1] = 1'b1;
            end else begin
                gnt[0] = 1'b1;
                gnt[1] = 1'b0;
            end
        end else if (req[0]) begin
            gnt[0] = 1'b1;
            gnt[1] = 1'b0;
        end else if (req[1]) begin
            gnt[0] = 1'b0;
            gnt[1] = 1'b1;
        end else begin
            gnt[0] = 1'b0;
            gnt[1] = 1'b0;
        end
    end

endmodule

module jk_flop (input J, K, clk,
                output reg Q, Qbar);
always @(posedge clk)
    if (J & K)
        Q <= ~Q;
    else if (J)
        Q <= 1;
    else if (K)
        Q <= 0;
    Qbar <= ~Q;
endmodule

