module modeSel (
	input clk, rst,
	input a, b, c, d,
	output reg [1:0] s
);
wire [3:0] i = {d, c, b, a};
	always @(posedge clk or posedge rst) begin
		if (rst) begin
			s <= 2'b00;
		end else begin
			case (i)
				4'b1000: s <= 2'b11;
				4'b0100: s <= 2'b10;
				4'b0010: s <= 2'b01;
				4'b0001: s <= 2'b00;
				default: s <= s;
			endcase
		end
	end
endmodule

module barrel_shifter_tb;
reg [7:0] in;
	reg [2:0] control;
	reg [7:0] out;
	reg [7:0] expected;
	reg [7:0] error;

	barrel_shifter uut (
		.in(in),
		.control(control),
		.out(out)
	);

	initial begin
		error = 0;
		in = 8'b10000000;
		control = 3'b000;
		expected = 8'b10000000;
		#10;
		if (out != expected) begin
			$display("Error: Shift by 4 failed");
			error = 1;
		end
		in = 8'b11111111;
		control = 3'b001;
		expected = 8'b11111111;
		#10;
		if (out != expected) begin
			$display("Error: Shift by 2 failed");
			error = 1;
		end
		in = 8'b11111111;
		control = 3'b010;
		expected = 8'b11111111;
		#10;
		if (out != expected) begin
			$display("Error: Shift by 1 failed");
			error = 1;
		end
		in = 8'b11111111;
		control = 3'b011;
		expected = 8'b11111111;
		#10;
		if (out != expected) begin
			$display("Error: Shift by 7 failed");
			error = 1;
		end
		if (error == 0) begin
			$display("All tests passed!");
		end
	end
endmodule

