module top_flag_ethiopia #(parameter CORDW=10) (  
    input  wire logic clk_pix,             
    input  wire logic sim_rst,             
    output      logic [CORDW-1:0] sdl_sx,  
    output      logic [CORDW-1:0] sdl_sy,  
    output      logic sdl_de,              
    output      logic [7:0] sdl_r,         
    output      logic [7:0] sdl_g,         
    output      logic [7:0] sdl_b          
    );
logic [7:0] sy;
    always_comb begin
        sy = sdl_sy[7:0];
    end

    logic [3:0] color;
    always_comb begin
        if (sy < 160) begin
            color = 4'h0;
        end else if (sy < 320) begin
            color = 4'hF;
        end else begin
            color = 4'hB;
        end
    end

    logic de;
    simple_480p display (
        .clk_pix,
        .rst_n(sim_rst),
        .sdl_de(de)
    );

    always_ff @(posedge clk_pix) begin
        sdl_sx <= 10'h000;
        sdl_sy <= sy;
        sdl_de <= de;
        sdl_r  <= {color, color};
        sdl_g  <= {color, color};
        sdl_b  <= {color, color};
    end

endmodule

