module UART_rx(
input wire clk,
input wire reset,
input wire rx_data_in,
output reg [7:0] rx_data_out
); 

parameter [31:0] BAUD_RATE=115200;
parameter [31:0] OVERSAMPLE=16;
reg [31:0] counter = 0;
reg [3:0] state = 0;
reg [7:0] data = 0;
  always @(posedge clk) begin
    if((reset == 1'b1)) begin
      counter <= 0;
      state <= 0;
      data <= 0;
    end
    else begin
      case(state)
      0 : begin
        if((rx_data_in == 1'b0)) begin
          state <= 1;
          counter <= 0;
        end
      end
      1 : begin
        if((counter == (OVERSAMPLE - 1))) begin
          state <= 2;
          counter <= 0;
        end
        else begin
          counter <= counter + 1;
        end
      end
      2 : begin
        if((counter == (OVERSAMPLE - 1))) begin
          state <= 3;
          counter <= 0;
        end
        else begin
          counter <= counter + 1;
        end
      end
      3 : begin
        if((rx_data_in == 1'b1)) begin
          state <= 0;
          data <= {data[6:0],rx_data_in};
          rx_data_out <= data;
        end
        else begin
          state <= 0;
          counter <= 0;
        end
      end
      default : begin
        state <= 0;
      end
      endcase
    end
  end
endmodule

module serial(clk, reset, rxD,sout,signal,counter);
input clk;      
input reset;    
input rxD;   

output reg [n-1:0]sout; 
output reg signal;   
output reg [31:0]counter;
parameter n = 30; 
parameter count = 4; 
reg [1:0]delay; 
top top1(clk,reset,rxD,s_in);
reg [7:0]s_in;
always@(posedge clk)
begin
    if(reset==1'b1)
    begin
        counter<=0;
        sout<=0;
        signal<=0;
        delay<=0;
    end
    else
    begin
        if(counter==count)
        begin
            delay<=1;
            counter<=0;
        end
        else
        begin
            delay<=0;
            counter<=counter+1;
        end
        if(delay==1)
        begin
            signal<=1;
        end
        else
        begin
            signal<=0;
        end
        sout<=s_in;
    end
end
endmodule

