module arbiter (
clock, 
reset, 
req_0,
req_1, 
gnt_0,
gnt_1
);

input clock, reset, req_0, req_1;
output gnt_0, gnt_1;
reg gnt_0, gnt_1;

always @(posedge clock or posedge reset) begin
	if (reset) begin
		gnt_0 <= 0;
		gnt_1 <= 0;
	end
	else begin
		if (req_0 && req_1) begin
			gnt_0 <= 1;
			gnt_1 <= 0;
		end
		else if (req_0) begin
			gnt_0 <= 1;
			gnt_1 <= 0;
		end
		else if (req_1) begin
			gnt_0 <= 0;
			gnt_1 <= 1;
		end
		else begin
			gnt_0 <= 0;
			gnt_1 <= 0;
		end
	end
end

endmodule

module NAND3C(Y,A,B,C);
 input A,B,C;
 output Y;
wire A__bar,B__bar;

 not (A__bar, A);
 not (B__bar, B);
 and (Y, A__bar, B__bar, C);

       specify

		specparam tpdLH_A_to_Y = (0.1:0.1:0.1);
		specparam tpdHL_A_to_Y = (0.1:0.1:0.1);
		specparam tpdLH_B_to_Y = (0.1:0.1:0.1);
		specparam tpdHL_B_to_Y = (0.1:0.1:0.1);
		specparam tpdLH_C_to_Y = (0.1:0.1:0.1);
		specparam tpdHL_C_to_Y = (0.1:0.1:0.1);
		specparam MacroType = "comb";



		(A => Y ) = ( tpdLH_A_to_Y, tpdHL_A_to_Y );
		(B => Y ) = ( tpdLH_B_to_Y, tpdHL_B_to_Y );
		(C => Y ) = ( tpdLH_C_to_Y, tpdHL_C_to_Y );
   endspecify

endmodule

module th22i
    #(parameter INITIAL = 0) (
      input	 init,
      input	 A, 
      input	 B, 
      output reg Q);
initial
	if (init)
	    Q <= #1 INITIAL;
	else
	    Q <= #1 0;

	always @*
	    if (A & B)
		Q <= #INITIAL 1;
	    else if (~A & ~B)
		Q <= #3+INITIAL 0;

endmodule

