module Bin2BCDConverter_4
#(
	parameter INPUT_BIT_WIDTH  = 8
)
(
    input [(INPUT_BIT_WIDTH-1):0] Input,
    output reg [3:0] Digit3,
    output reg [3:0] Digit2,
    output reg [3:0] Digit1,
    output reg [3:0] Digit0
);
always @(Input) begin
		for (int i = 0; i < INPUT_BIT_WIDTH; i = i + 1) begin
			if (Digit3 >= 5) begin
				Digit3 = Digit3 + 3;
			end
			if (Digit2 >= 5) begin
				Digit2 = Digit2 + 3;
			end
			if (Digit1 >= 5) begin
				Digit1 = Digit1 + 3;
			end
			if (Digit0 >= 5) begin
				Digit0 = Digit0 + 3;
			end
			Digit3 = {Digit3[2:0], Digit3[3]};
			Digit2 = {Digit2[2:0], Digit2[3]};
			Digit1 = {Digit1[2:0], Digit1[3]};
			Digit0 = {Digit0[2:0], Digit0[3]};
			if (i == 0) begin
				Digit0[0] = Input[0];
			end else if (i == 1) begin
				Digit0[0] = Input[1];
				Digit1[0] = Input[0];
			end else if (i == 2) begin
				Digit0[0] = Input[2];
				Digit1[0] = Input[1];
				Digit2[0] = Input[0];
			end else if (i == 3) begin
				Digit0[0] = Input[3];
				Digit1[0] = Input[2];
				Digit2[0] = Input[1];
				Digit3[0] = Input[0];
			end
		end
	end
endmodule

