            .terminalCount(terminalCounts[i])
         );
         if (i == 0) begin
            assign enable[i] = 1'b1;
         end else begin
            assign enable[i] = terminalCounts[i-1];
         end
      end
   endgenerate
   assign outCount = counts[numOfCounters-1];
endmodule

