                end else begin
                    next_state <= B;
                end
            end
        endcase
    end
    always @(state) begin
        case (state)
            A: begin
                out <= 1'b0;
            end
            B: begin
                out <= 1'b0;
            end
            C: begin
                out <= 1'b0;
            end
