module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    output walk_left,
    output walk_right
);
reg walk_left_reg;
    reg walk_right_reg;
    reg walk_left_next;
    reg walk_right_next;

    always @(posedge clk) begin
        if (areset) begin
            walk_left_reg <= 1'b1;
            walk_right_reg <= 1'b0;
        end else begin
            walk_left_reg <= walk_left_next;
            walk_right_reg <= walk_right_next;
        end
    end

    always @(*) begin
        walk_left_next = 1'b0;
        walk_right_next = 1'b0;
        if (bump_left) begin
            walk_right_next = 1'b1;
        end
        if (bump_right) begin
            walk_left_next = 1'b1;
        end
        if (bump_left && bump_right) begin
            walk_left_next = 1'b1;
            walk_right_next = 1'b1;
        end
    end

    assign walk_left = walk_left_reg;
    assign walk_right = walk_right_reg;

endmodule

