                        state <= 3;
                        byte <= in;
                        byte_count <= byte_count + 1;
                    end
                end
                3: begin
                    if (byte_count == 2) begin
                        state <= 0;
                        done_reg <= 1;
                    end else begin
                        state <= 0;
                        done_reg <= 0;
                    end
                end
            endcase
        end
    end

    assign done = done_reg;

