    always @(posedge clk or posedge reset) begin
        if (reset) begin
            _z_next <= 2'b00;
        end else begin
            _z_next <= _z_d_next;
        end
    end
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            _z_next <= 2'b00;
        end else begin
            case (_z_d)
                2'b00: _z_next <= w ? 2'b01 : 2'b00;
