module TopModule(
    input  clk,
    input  resetn,
    input  r[2:0],
    output g[2:0]
    );
reg [1:0] state;
    reg [1:0] next_state;
    reg [1:0] g;
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= 2'b00;
        end else begin
            state <= next_state;
        end
    end
    always @(state, r) begin
        case (state)
            2'b00: begin
                if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state = 2'b00;
                end else if (r[0] == 1'b1 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state = 2'b01;
                end else if (r[0] == 1'b0 && r[1] == 1'b1 && r[2] == 1'b0) begin
                    next_state = 2'b10;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b1) begin
                    next_state = 2'b11;
                end
            end
            2'b01: begin
                if (r[0] == 1'b1 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state = 2'b01;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state = 2'b00;
                end else if (r[0] == 1'b0 && r[1] == 1'b1 && r[2] == 1'b0) begin
                    next_state = 2'b10;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b1) begin
                    next_state = 2'b11;
                end
            end
            2'b10: begin
                if (r[0] == 1'b0 && r[1] == 1'b1 && r[2] == 1'b0) begin
                    next_state = 2'b10;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state = 2'b00;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b1) begin
                    next_state = 2'b11;
                end
            end
            2'b11: begin
                if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b1) begin
                    next_state = 2'b11;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state = 2'b00;
                end else if (r[0] == 1'b0 && r[1] == 1'b1 && r[2] == 1'b0) begin
                    next_state = 2'b10;
                end
            end
        endcase
    end
    always @(state) begin
        case (state)
            2'b00: begin
                g[0] = 1'b0;
                g[1] = 1'b0;
                g[2] = 1'b0;
            end
            2'b01: begin
                g[0] = 1'b1;
                g[1] = 1'b0;
                g[2] = 1'b0;
            end
            2'b10: begin
                g[0] = 1'b0;
                g[1] = 1'b1;
                g[2] = 1'b0;
            end
            2'b11: begin
                g[0] = 1'b0;
                g[1] = 1'b0;
                g[2] = 1'b1;
            end
        endcase
    end
endmodule

