module TopModule(
input wire clk,
input wire reset,
input wire data,
input wire done_counting,
input wire ack,
output reg shift_ena,
output reg counting,
output reg done
); 

parameter [1:0]
  S_IDLE = 0,
  S_WAIT = 1,
  S_COUNT = 2,
  S_DONE = 3;
reg [1:0] state;
reg [1:0] next_state;
reg [1:0] count;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      state <= S_IDLE;
    end else begin
      state <= next_state;
    end
  end
  always @(state, data) begin
    case(state)
    S_IDLE : begin
      if((data == 1'b1)) begin
        next_state <= S_WAIT;
      end
      else begin
        next_state <= S_IDLE;
      end
    end
    S_WAIT : begin
      if((data == 1'b1)) begin
        next_state <= S_WAIT;
      end
      else begin
        next_state <= S_COUNT;
      end
    end
    S_COUNT : begin
      if((count == 4)) begin
        next_state <= S_DONE;
      end
      else begin
        next_state <= S_COUNT;
      end
    end
    S_DONE : begin
      if((ack == 1'b1)) begin
        next_state <= S_IDLE;
      end
      else begin
        next_state <= S_DONE;
      end
    end
    default : begin
      next_state <= S_IDLE;
    end
    endcase
  end
  always @(state) begin
    case(state)
    S_IDLE : begin
      shift_ena <= 1'b0;
      counting <= 1'b0;
      done <= 1'b0;
    end
    S_WAIT : begin
      shift_ena <= 1'b0;
      counting <= 1'b0;
      done <= 1'b0;
    end
    S_COUNT : begin
      shift_ena <= 1'b1;
      counting <= 1'b1;
      done <= 1'b0;
    end
    S_DONE : begin
      shift_ena <= 1'b0;
      counting <= 1'b0;
      done <= 1'b1;
    end
    default : begin
      shift_ena <= 1'b0;
      counting <= 1'b0;
      done <= 1'b0;
    end
    endcase
  end
  always @(posedge clk) begin
    if((state == S_COUNT)) begin
      count <= count + 1;
    end
  end
endmodule

