module TopModule (
  input clk,
  input reset,
  input w,
  output z
);
reg [1:0] state;
  reg _z;

  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
    end else begin
      case (state)
        2'b00: if (w) state <= 2'b01; else state <= 2'b00;
        2'b01: if (w) state <= 2'b10; else state <= 2'b00;
        2'b10: if (w) state <= 2'b11; else state <= 2'b00;
        2'b11: if (w) state <= 2'b10; else state <= 2'b00;
      endcase
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      _z <= 1'b0;
    end else begin
      case (state)
        2'b00: _z <= 1'b0;
        2'b01: _z <= 1'b0;
        2'b10: _z <= 1'b0;
        2'b11: _z <= 1'b1;
      endcase
    end
  end

  assign z = _z;

endmodule

