module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);
reg [1:0] state;
  reg [2:0] g;

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      state <= 2'b00;
    end else begin
      case (state)
        2'b00: begin
          if (r[0] | r[1] | r[2]) begin
            state <= 2'b01;
          end
        end
        2'b01: begin
          if (r[0] & r[1] & r[2]) begin
            state <= 2'b10;
          end else if (r[0] & r[1]) begin
            state <= 2'b00;
          end else if (r[0] & r[2]) begin
            state <= 2'b01;
          end else if (r[1] & r[2]) begin
            state <= 2'b01;
          end else if (r[0]) begin
            state <= 2'b10;
          end else if (r[1]) begin
            state <= 2'b01;
          end else if (r[2]) begin
            state <= 2'b01;
          end else begin
            state <= 2'b00;
          end
        end
        2'b10: begin
          if (r[0] | r[1] | r[2]) begin
            state <= 2'b01;
          end
        end
      endcase
    end
  end

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      g <= 3'b000;
    end else begin
      case (state)
        2'b00: begin
          g <= 3'b000;
        end
        2'b01: begin
          g <= 3'b001;
        end
        2'b10: begin
          g <= 3'b010;
        end
      endcase
    end
  end

endmodule

